-- 1. CREATE MENU_ITEMS TABLE
CREATE TABLE IF NOT EXISTS public.menu_items (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    sub_category TEXT DEFAULT '',
    price INTEGER NOT NULL DEFAULT 0,
    tag TEXT DEFAULT '',
    dietary TEXT DEFAULT 'veg',
    description TEXT DEFAULT '',
    details JSONB DEFAULT '[]'::jsonb,
    image TEXT DEFAULT '',
    alt TEXT DEFAULT '',
    is_available BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- Enable Row Level Security (RLS)
ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;

-- Allow public read access to all menu items
DROP POLICY IF EXISTS "Public menu items read access" ON public.menu_items;
CREATE POLICY "Public menu items read access"
    ON public.menu_items FOR SELECT
    USING (true);

-- Allow public write access (for Staff Admin management)
DROP POLICY IF EXISTS "Public menu items insert access" ON public.menu_items;
CREATE POLICY "Public menu items insert access"
    ON public.menu_items FOR INSERT
    WITH CHECK (true);

DROP POLICY IF EXISTS "Public menu items update access" ON public.menu_items;
CREATE POLICY "Public menu items update access"
    ON public.menu_items FOR UPDATE
    USING (true)
    WITH CHECK (true);

DROP POLICY IF EXISTS "Public menu items delete access" ON public.menu_items;
CREATE POLICY "Public menu items delete access"
    ON public.menu_items FOR DELETE
    USING (true);

-- 2. CREATE REVIEWS TABLE
CREATE TABLE IF NOT EXISTS public.reviews (
    id BIGSERIAL PRIMARY KEY,
    author TEXT NOT NULL,
    role TEXT DEFAULT 'Guest',
    rating INTEGER DEFAULT 5,
    quote TEXT NOT NULL,
    initials TEXT DEFAULT '',
    avatar_bg TEXT DEFAULT 'bg-brand-sage text-brand-forest',
    is_approved BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public reviews read access" ON public.reviews;
CREATE POLICY "Public reviews read access"
    ON public.reviews FOR SELECT
    USING (is_approved = true);

DROP POLICY IF EXISTS "Public reviews insert access" ON public.reviews;
CREATE POLICY "Public reviews insert access"
    ON public.reviews FOR INSERT
    WITH CHECK (true);

-- 3. SEED 163 AUTHENTIC MENU ITEMS
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    sub_category = EXCLUDED.sub_category,
    price = EXCLUDED.price,
    tag = EXCLUDED.tag,
    dietary = EXCLUDED.dietary,
    description = EXCLUDED.description,
    details = EXCLUDED.details,
    image = EXCLUDED.image,
    alt = EXCLUDED.alt,
    is_available = EXCLUDED.is_available;
